algorithm LargestOfSeries
    define mutable count as integer <- 0;
    define mutable number as integer <- 0;
    define mutable largest as integer <- 0;
    read count;
    read largest;
    for i <- 2 to count step 1 do
        read number;
        if number > largest then
            largest <- number;
        endIf
    endFor
    write largest;
endAlgorithm
